        last = max((c for c, value in enumerate(row) if value != bg), default=-1)
        # Find the shortest motif appearing twice consecutively at the right
        # end of the observed portion, then continue that motif to the edge.
        period = None
        for p in range(1, (last + 1) // 2 + 1):
            if all(row[c] == row[c-p] for c in range(last-p+1, last+1)):
                period = p
                break
        if period is not None:
            for c in range(last+1, width):
                if row[c-period] != bg:
                    out[r][c] = 1
    return out

